 blocked:=false;BEGIN PERFORM tw_accounting_save_entry(gen_random_uuid(),c,'2026-01-15','','Missing directory entry',NULL,'manual','[{"account":"411001","debit":"0","credit":"10"},{"account":"111001","debit":"10","credit":"0"}]');EXCEPTION WHEN raise_exception THEN blocked:=SQLERRM LIKE '%Select the client%';END;
